<script setup lang="ts">
import {localize} from './localization';

import {computed,ref,watch} from 'vue';
import {useDraftHistory} from './modules/useDraftHistory';
import {useSession} from './store';
import {modelPartLabel} from './modules/model-labels';
import {bodyParts,partName,sideName,namedPart} from '../../../packages/reference/body-parts';
import type {BodyPart,BodySide} from '../../../packages/reference/body-parts';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh'),kind=ref<''|'body'|'body-feet'|'head'|'paw'|'foot'>(''),boundary=ref<number>(),modelSide=ref<BodySide>('unknown');
const surface=computed(()=>store.data.project?.surface),groups=computed(()=>[...new Set(surface.value?.faces.map(f=>f.region)??[])].map(region=>({region,...(surface.value?.partAssignments?.find(a=>a.region===region)??namedPart(region))}))),unclassified=computed(()=>groups.value.filter(g=>g.part==='unknown').length);
const historyPanel=ref<HTMLElement>(),history=useDraftHistory(()=>({kind:kind.value,boundary:boundary.value,side:modelSide.value}),v=>{kind.value=v.kind;boundary.value=v.boundary;modelSide.value=v.side;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
watch(()=>JSON.stringify([surface.value?.id,surface.value?.partAssignments]),()=>history.reset(()=>{kind.value='';boundary.value=undefined;modelSide.value='unknown';}));
async function classify(){const p=store.data.project,selectedKind=kind.value;if(p&&selectedKind)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.classify',kind:selectedKind,...(selectedKind==='paw'||selectedKind==='foot'?{side:modelSide.value}:{}),...(selectedKind==='body-feet'&&Number.isFinite(boundary.value)?{footBoundaryMm:boundary.value}:{})}));}
async function assign(region:string,part:BodyPart,side:BodySide){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'surface.anatomy',assignments:groups.value.map(g=>g.region===region?{region,part,side}:g)}));}
</script>
<template><section v-if="surface" ref="historyPanel" class="model-anatomy" aria-label="模型部位识别"><h3>{{zh?'模型包含哪些部位？':localize('Which parts does this model contain?')}}</h3><p>{{zh?'带名称的模型部件自动读取；未知名称需要指定类型。身体壳会尝试按直立 T 姿势识别手臂和双腿，姿势特殊时逐组修正；没有的部位会跳过。':localize('Assign unnamed geometry a type. Upright T-pose body shells suggest arms and legs; correct unusual poses by group. Absent parts are skipped.')}}</p><strong>{{zh?'已识别':localize('Recognized')}}: {{[...new Set(groups.filter(g=>g.part!=='unknown').map(g=>partName(g.part,zh)))].join(' · ')||'—'}} <span v-if="unclassified">· {{unclassified}} {{zh?'组待分类':localize('unclassified groups')}}</span></strong><div v-if="unclassified||groups.some(g=>g.part==='body')" class="classify-options"><label>{{zh?'当前模型类型':localize('Current model type')}}<select v-model="kind" aria-label="模型类型"><option value="">{{zh?'通用模型（未指定身体部位）':localize('Generic mesh (no body classification)')}}</option><option value="body">{{zh?'身体（没有脚）':localize('Body without feet')}}</option><option value="body-feet">{{zh?'身体（包含脚）':localize('Body with feet')}}</option><option value="head">{{zh?'仅头部':localize('Head only')}}</option><option value="paw">{{zh?'仅手爪':localize('Paws only')}}</option><option value="foot">{{zh?'仅脚':localize('Feet only')}}</option></select></label><label v-if="kind==='paw'||kind==='foot'">{{zh?'这个模型属于哪侧？':localize('Which side is this model?')}}<select v-model="modelSide" aria-label="单部位模型左右侧"><option v-for="side in (['unknown','left','right'] as const)" :key="side" :value="side">{{sideName(side,zh)}}</option></select><small>{{zh?'按角色自身左右侧，不是屏幕左右侧。未指定时不会叠贴两侧花纹。':localize('Use character left/right, not screen left/right. Unknown sides are not overlaid.')}}</small></label><label v-if="kind==='body-feet'">{{zh?'脚腕分界 Y mm（留空取下方 15%）':localize('Ankle Y mm (blank: bottom 15%)')}}<input v-model.number="boundary" type="number"><small>{{zh?'此高度以下按脚分类；检查预览后可撤销或逐组修正。':localize('Geometry below this height is feet. Inspect and correct groups or undo.')}}</small></label><button :disabled="store.busy||!kind" @click="classify">{{zh?'识别并保存模型部位':localize('Classify and save model parts')}}</button></div><details><summary>{{zh?'逐部件修正分类 / 左右侧':localize('Correct each group / side')}}</summary><div v-for="g in groups" :key="g.region" class="part-group"><span>{{modelPartLabel(g.region,zh)}}</span><select :value="g.part" :aria-label="'模型部位 '+g.region" @change="assign(g.region,($event.target as HTMLSelectElement).value as BodyPart,g.side)"><option v-for="part in bodyParts" :key="part" :value="part">{{partName(part,zh)}}</option></select><select :value="g.side" :aria-label="'模型左右侧 '+g.region" @change="assign(g.region,g.part,($event.target as HTMLSelectElement).value as BodySide)"><option v-for="side in (['center','left','right','unknown'] as const)" :key="side" :value="side">{{sideName(side,zh)}}</option></select></div></details></section></template>
<style scoped>.model-anatomy{padding:15px;border-block:1px solid var(--border);font-size:12px}.model-anatomy p,small{color:var(--text-muted);line-height:1.7}h3{margin:0 0 8px}.classify-options{display:grid;gap:10px;margin:12px 0}.classify-options small{display:block}.part-group{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:6px;margin-top:8px;align-items:center}.part-group span{overflow-wrap:anywhere}details{margin-top:12px}details>div{font-size:10px}</style>
